using System;using UnityEngine;
namespace LWS.TruckTargetLaunch.Editor {
public static class TargetFixtures {
 public static void Run(){int checks=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Target fixture: "+label);checks++;};check(TargetRules.Zone(0,0)==100&&TargetRules.Zone(2.3f,0)==100,"tiny bullseye with inclusive edge");check(TargetRules.Zone(2.301f,0)==50&&TargetRules.Zone(8,0)==50&&TargetRules.Zone(8.001f,0)==25,"precision and medium boundaries");check(TargetRules.Zone(18,0)==25&&TargetRules.Zone(18.001f,0)==10&&TargetRules.Zone(30,0)==10&&TargetRules.Zone(30.001f,0)==0,"outer boundaries/miss");check(TargetRules.Zone(6,0,6,0)==100&&TargetRules.Zone(-6,0,6,0)==25,"shared moving precision center follows visible layout");check(TargetRules.TopContact(1,-6,4,4)&&!TargetRules.TopContact(0,-6,4,4)&&!TargetRules.TopContact(-1,-6,3,4)&&!TargetRules.TopContact(1,3,4,4),"descending top only; side/underside/upward rejection");var r=new TargetRules();r.Reset(4);check(r.Lock(0,100)&&!r.Lock(0,50)&&r.totals[0]==100&&r.attempts[0]==1,"one authoritative result per delivery");check(!r.Advance()&&r.Round==1,"all simultaneous participants must resolve");for(int i=1;i<4;i++)r.Lock(i,10);r.Advance();check(r.Round==2&&Array.TrueForAll(r.resolved,b=>!b),"complete round advances once and resets delivery ownership");r.Reset(2);for(int round=0;round<5;round++){r.Lock(0,25);r.Lock(1,25);r.Advance();}check(!r.Complete&&r.Round==6&&r.Eligible==3&&r.attempts[0]==5&&r.attempts[1]==5,"five equal-opportunity launches then tied-leader extra round");r.Lock(0,50);check(!r.Advance()&&!r.Complete,"first extra shooter cannot win before other's equal attempt");r.Lock(1,10);r.Advance();check(r.Complete&&r.Winner==0&&r.attempts[0]==6&&r.attempts[1]==6,"extra round resolves after equal opportunity");check(!r.Lock(1,100)&&r.Winner==0,"post-result collision cannot change winner");r.Reset(3);for(int round=0;round<5;round++){r.Lock(0,50);r.Lock(1,50);r.Lock(2,10);r.Advance();}check(r.Eligible==3&&r.resolved[2]&&!r.Lock(2,100),"only tied leaders deliver extras");r.Reset(1);for(int i=0;i<5;i++){r.Lock(0,25);r.Advance();}check(r.Complete&&r.totals[0]==125&&r.attempts[0]==5,"solo completes exactly five attempts for personal best");Debug.Log("TARGET_RULE_FIXTURES_PASS "+checks);}
}
}
